  function put(q, source) { q.source = source || '原题库'; addQ(q); }

  put(Q.judge("eth-005", "eth-main", "t1", "t1-s3", "教师职业道德只约束教师的教学行为，与日常生活无关。", true, 1, "教师相关校内外言行仍可能产生育人示范和权益影响，不能一概排除职业责任；这不等于私人生活的一切细节都应受到无限监督。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-006", "eth-main", "t1", "t1-s2", "教师劳动具有示范性，教师的一言一行都可能成为学生模仿的对象。", true, 1, "学生具有向师性，教师的品德、态度、言行会潜移默化地影响学生，这正是强调师德的原因。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-009", "eth-main", "t4", "t4-s3", "\"严谨治学\"要求教师（　　）", ["只重视论文数量", "恪守学术规范，反对学术不端", "拒绝一切学术批评", "把科研与教学割裂"], "B", 2, "严谨治学强调求真务实、恪守学术规范、尊重他人学术成果，反对抄袭、剽窃、篡改数据等学术不端行为。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-010", "eth-main", "t1", "t1-s3", "新时代高校教师职业行为十项准则中，居于首位的是（　　）", ["坚定政治方向", "传播优秀文化", "关心爱护学生", "坚守廉洁自律"], "A", 2, "十项准则以\"坚定政治方向\"为首，体现师德建设把政治标准放在首位的要求。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-014", "eth-main", "t4", "t4-s3", "\"严谨治学\"只要求教师做好科研，与教学无关。", true, 1, "严谨治学既指向科研，也指向教学：认真备课、精心组织教学、严格学业标准同样是严谨治学的体现。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-015", "eth-main", "t1", "t1-s3", "十项准则明确了高校教师职业行为的基本底线，教师违反准则应依规依法处理。", true, 1, "准则具有明确的职业约束力；不能把所有职业失范都等同于违法犯罪或同一种处分。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-028", "eth-main", "t3", "t3-s1", "教书育人意味着教师只需上好课，育人主要由辅导员负责。", true, 1, "教书育人是每位教师的本职，专业课教师同样承担育人责任，辅导员不能替代。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-029", "eth-main", "t3", "t3-s2", "教师可以不顾育人责任，在课堂上编造事实或传播损害学生合法权益的言论。", true, 1, "课堂表达应真实、负责并尊重学生权益，正常学术探讨与编造事实、侵权言论需要区分。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-032", "eth-main", "t7", "t7-s3", "把师德要求转化为可检验的实际行为，最直接依靠（　　）。", ["闭门读书", "教育教学实践", "参加培训", "写心得体会"], "B", 2, "实践使认识落实为行为并得到反馈；高校教师还可在科研、社会服务和管理等履职活动中锤炼师德。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-033", "eth-main", "t6", "t6-s2", "我国师德考核实行的基本导向是（　　）", ["以论文数量为第一标准", "师德第一标准，师德失范\"一票否决\"", "以学生考试成绩为标准", "以教龄长短为标准"], "B", 2, "新时代教师评价改革明确把师德师风作为第一标准，师德失范在职称评聘、评优评先中实行一票否决。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-034", "eth-main", "t7", "t7-s2", "师德修养的主要方法有（　　）", ["学习", "实践", "内省", "闭门造车"], ["A", "B", "C"], 3, "此外还有榜样示范、反思总结、自我评价等方法。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-035", "eth-main", "t6", "t6-s2", "师德失范行为的处理方式包括（　　）", ["批评教育", "诫勉谈话", "通报批评", "一律开除"], ["A", "B", "C"], 3, "指导意见按性质情节区分处理，批评教育、诫勉谈话、通报批评可用于相应情形；不能一律开除，资格处理还须符合法定条件并由有权主体实施。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-036", "eth-main", "t7", "t7-s1", "师德修养主要靠外部约束，与自我反思关系不大。", true, 1, "师德修养是内外因共同作用的结果，自律是根本，内省、慎独等自我修养方法至关重要。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-040", "eth-main", "t6", "t6-s2", "高校师德评价应坚持的基本取向是（　　）", ["以学生评教分数为唯一依据", "多元主体参与，注重日常表现与发展性评价", "只看获奖和论文数量", "由学校领导单独决定"], "B", 2, "评价应结合可核查的日常表现以及学生、同行等相关方面的合理反馈，不以人气、荣誉或单一主体意见替代事实。"), "既有练习；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-001", "eth-drill", "t1", "t1-s2", "教师必须十分重视自身的发展，做到以身作则，为人师表，这体现了教师劳动的哪一特点。 （ ）", ["复杂性、创造性", "连续性、广延性", "长期性、间接性", "主体性、示范性"], "D", 2, "教师自身的行为和品格参与育人，题干突出以自身行为作榜样，因此D中的主体性与示范性最切合。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-016", "eth-drill", "t1", "t1-s2", "（ ）反映了教师这一行业的本质特征，指出了教师这一行业和其他行业不同的根本所在。", ["为人师表  ", "献身教育  ", "教书育人  ", "公而忘私"], "C", 2, "教师通过教学促进学生知识、能力与人格发展，题目考查其育人职责，C比一般职业态度的选项更直接。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-x-021", "eth-drill", "t1", "t1-s3", "教师职业道德是指教师在从事教育劳动过程中形成比较稳定的（ ）的总和。", ["道德观念", "行为规范", "道德品质", "专业技能"], ["A", "B", "C"], 3, "职业道德涉及应有的道德认识、行为要求及稳定品质；专业技能与道德相关，但不能直接等同职业道德。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-x-024", "eth-drill", "t2", "t2-s1", "高校教师对学生进行教育活动所使用的工具和手段靠自身的（ ）。", ["道德品质  ", "情感意志 ", "文化知识 ", "职称水平"], ["A", "B", "C"], 3, "教师的知识、情感意志和道德品质都会参与教育影响，职称是身份或评价结果，不能替代这些实际育人条件。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-027", "eth-drill", "t1", "t1-s3", "教师职业道德区别于其他职业道德的显著标志就是（ ）。", ["为人师表", "清正廉洁  ", "敬业爱业    ", "团结协作"], "A", 2, "为人师表把教师自身行为纳入育人过程，是教师职业示范责任的突出体现；廉洁、敬业、协作并非教师职业独有。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-x-033", "eth-drill", "t3", "t3-s2", "下列哪些倾向可能损害教师的履职责任？", ["只重个人金钱收益", "轻视教育事业与岗位职责", "只计个人实惠而忽视学生权益", "淡化对学生的职业责任"], ["A", "B", "C", "D"], 3, "题目考查具体价值取向与履职风险，不宣称这些倾向是所有教师或某一时期群体的调查现状。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-046", "eth-drill", "t1", "t1-s2", "依2011年《规范》“敬业爱生”的措辞，教师应忠诚于（　　）。", ["党的教育事业", "民族的教育事业", "国家的教育事业", "人民的教育事业"], "D", 2, "规范的表述是忠诚人民教育事业，本题限定文件措辞，D与之对应。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-062", "eth-drill", "t2", "t2-s1", "下列对教育中人道主义要求的概括，最完整的是（　　）。", ["要给予教育工作者充分的尊重", "要给予学生充分的人文关怀", "对犯错者要给予批评、教育与帮助", "对人的普遍关怀和尊重"], "D", 2, "教育中的人道关怀强调尊重人及其尊严，覆盖学生和教师；D是整体表述，不能缩减成只关心某一方或某一类情形。"), "《师德练习题》；v1.11.0复核整理，解析为自编补充");
  put(Q.single("eth-x-081", "eth-drill", "t6", "t6-s1", "处理好同事之间的道德准则是：", ["君子之交淡如水", "走自己的路，让人说去吧", "团结协作，共同育人"], "C", 2, "同事间需要互相尊重、配合和共同承担育人责任，C符合合作伦理；自我封闭或不顾影响的做法不利于共同育人。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-x-091", "eth-drill", "t4", "t4-s2", "下列哪些因素可能增加科研失信风险？", ["监督机制缺失", "评价与管理制度存在缺陷", "支付合规版面费本身必然构成学术腐败", "缺乏求真守信的学风"], ["A", "B", "D"], 3, "监督、评价制度与学风可能影响失信风险；正常合规付费本身不能等同科研失信，需要区分虚假交易和不当行为。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.multiple("eth-x-092", "eth-drill", "t6", "t6-s1", "教师与学校管理人员交往，符合管理道德的做法包括（　　）。", ["配合合法合理的工作安排", "认真听取有依据的批评并说明自己的意见", "相互尊重人格与正当权利", "通过适当渠道提出建设性意见"], ["A", "B", "C", "D"], 3, "合作、理性沟通、人格尊重和依法参与管理可以并存；尊重管理者不等于无条件接受违法或侵权要求。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-093", "eth-drill", "t1", "t1-s3", "高校教师承担育人职责，应重视自身行为对学生的示范影响。", true, 1, "教师职业责任包含示范要求，不等于断言所有教师都比其他人道德更高。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-094", "eth-drill", "t4", "t4-s2", "行政权力不当干预学术评价且缺少监督，会增加学术失范风险。", true, 1, "问题在于越权、不公和监督缺失，而不是否认行政管理与学术治理需要依职责协调。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-096", "eth-drill", "t1", "t1-s1", "高校只需要培养少数精英，不需要承担其他人才培养、科学研究或社会服务。", true, 1, "高等教育的任务不能缩为少数精英培养，还须依法开展相应人才培养、科研与社会服务。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-098", "eth-drill", "t1", "t1-s1", "高校只要能够盈利，就可以不再承担人才培养责任。", true, 1, "高校承担公共教育与人才培养责任，经营收益不能替代办学目的或免除育人义务。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-101", "eth-drill", "t7", "t7-s3", "师德教育应当制度化。（对；不对）", true, 1, "稳定的培训、评价、监督和责任机制有助于把师德要求持续落实，不能只靠一次活动或个人表态。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-105", "eth-drill", "t7", "t7-s2", "对于传统师德也应该取其精华，弃其糟粕。", true, 1, "学习传统师德应结合现代学生权利和育人要求作批判继承，既不能全盘否定，也不能照搬不适当的旧观念。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-106", "eth-drill", "t1", "t1-s3", "师德的示范作用，与教师职业劳动具有示范性相联系。", true, 1, "教师日常言行可成为学生观察和模仿的对象，因此职业道德具有示范意义。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-107", "eth-drill", "t1", "t1-s3", "市场环境会影响职业实践，教师应警惕逐利冲动损害育人责任。", true, 1, "社会环境和利益激励会影响职业实践，教师仍需依据育人责任判断，不能以市场竞争为由放弃伦理底线。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-110", "eth-drill", "t1", "t1-s3", "教师的主要任务就是教书育人，而穿着打扮等生活习惯纯属个人的私事。", true, 1, "职业规范并非无限介入私人生活，但相关言行可能产生示范或侵权影响，不能以“私人习惯”概括排除全部责任。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-111", "eth-drill", "t7", "t7-s3", "教师职业道德建设在教师队伍建设中具有首要和基础作用。", true, 1, "师德关系教师如何履行育人职责，长效机制要求把师德建设置于教师队伍建设的重要基础位置。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-113", "eth-drill", "t1", "t1-s3", "教师职业面向不特定的学生，所以教师职业道德也没有适用的针对性。", true, 1, "教师面对具体学生和教育任务，需要遵循相应职责与伦理边界，教育对象变化不意味着规范失去针对性。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-114", "eth-drill", "t1", "t1-s3", "教师职业道德的要求仅仅限于教师行业，因此相对于其他行业来说内容比较单一。", true, 1, "师德关联教育、教学、科研、社会服务和管理等多种关系，行业性不意味着内容单一。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-117", "eth-drill", "t1", "t1-s3", "教师的公开行为可能影响公众对教师职业的信任和社会风气。", true, 1, "教师的公共表达和行为具有社会影响，但不能断言每次行为都直接影响全体社会成员。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-118", "eth-drill", "t7", "t7-s2", "博学多才要求教师掌握一切先进的科学文化知识。", true, 1, "教师需要持续学习并掌握履职所需知识，不能把博学理解为穷尽一切科学文化知识。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
  put(Q.judge("eth-x-119", "eth-drill", "t6", "t6-s1", "教师是教学的主人，学校的主人。办学应以教师为中心。", true, 1, "高校治理需要依法参与和尊重多方主体，育人活动应重视学生发展，不能将办学简化为只围绕教师个人需求。"), "《师德合并卷》；v1.11.0复核整理，解析为自编补充");
