  put(Q.judge("eth-bal-judge-040", "eth-main", "t6", "t6-s2", "公平诚信要求教师避免在推荐和奖励中徇私舞弊。", true, 1, "相关权限应依标准、事实和程序行使。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
