  put(Q.judge("eth-bal-judge-042", "eth-main", "t3", "t3-s3", "为追求课堂效果，教师可以把未经证实的材料明确包装成确定事实。", true, 1, "生动表达不能以牺牲事实准确性为代价。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-043", "eth-main", "t5", "t5-s4", "教师开展有偿专业服务时，应合理说明服务能力与承诺范围。", true, 1, "不能利用教师身份误导合作方。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-044", "eth-main", "t2", "t2-s3", "教师可以默许他人以自己的名义出售虚假的课程通过承诺。", true, 1, "应维护职业诚信，不能参与或纵容不当交易。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-045", "eth-main", "t3", "t3-s1", "传播优秀文化可以与专业课程内容结合，不必仅限于口号宣讲。", true, 1, "价值引导可以融入真实专业学习。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-046", "eth-main", "t1", "t1-s2", "教师转发涉及学生的负面传闻前，应核实事实并考虑人格与隐私影响。", true, 1, "信息传播责任不能由“只是转发”排除。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-047", "eth-main", "t3", "t3-s3", "课堂上所有不同意见都应被直接当作师德问题处理。", true, 1, "应区分正常学术探讨与真正违反规范的言行。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-048", "eth-main", "t4", "t4-s3", "有合理学术分歧时，教师仍应以证据论证而不是人身攻击回应。", true, 1, "理性讨论和尊重人格是重要职业要求。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-049", "eth-main", "t6", "t6-s2", "只要出于扶持熟人目的，在评审中改变标准就符合关爱要求。", true, 1, "关爱不能成为徇私和损害公平的理由。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-050", "eth-main", "t5", "t5-s4", "教师使用公共资源应依相关制度，不应任意转作私人收益。", true, 1, "廉洁与公共责任也涉及资源使用。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-051", "eth-main", "t1", "t1-s3", "职业行为准则只约束青年教师，知名教师可以不受约束。", true, 1, "身份和荣誉不能豁免基本职业规范。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-052", "eth-main", "t1", "t1-s2", "教师了解制度变动后及时调整做法，是负责任履职的一部分。", true, 1, "沿用失效习惯不能自动证明行为适当。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-053", "eth-main", "t6", "t6-s2", "接受监督不等于必须无条件认同所有未经核实的指控。", true, 1, "监督与事实核查、正当程序应结合。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-054", "eth-main", "t3", "t3-s3", "教师依据明确课程标准评分，应避免家庭关系等无关因素影响。", true, 1, "学业评价应围绕真实学习表现。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-055", "eth-main", "t2", "t2-s3", "对所有学生提供完全相同形式的支持，是公平的唯一实现方式。", true, 1, "公平可以包含依据合理需要的差异化支持。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-056", "eth-main", "t2", "t2-s3", "学生对教学提出合理建议，不应因此失去正常参与课程的机会。", true, 1, "合理反馈不应成为报复对象。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-057", "eth-main", "t2", "t2-s3", "教师因学生不参加私人聚会而降低其作业分数，属于正当严格管理。", true, 1, "私人交往不能与学业评价不当捆绑。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-058", "eth-main", "t3", "t3-s3", "对小组合作成绩的说明可以同时包含共同成果与个人贡献。", true, 1, "这有助于兼顾合作与个人责任。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-059", "eth-main", "t4", "t4-s3", "导师仅凭职务身份就可以永久独占学生实际完成的研究成果。", true, 1, "成果署名与权益应尊重贡献和学术规范。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-060", "eth-main", "t2", "t2-s3", "师生沟通中认真听取学生解释，有助于避免基于片面信息判断。", true, 1, "尊重并不排斥最终依规则作出决定。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-061", "eth-main", "t2", "t2-s3", "教师可以以了解学生为名，无限制收集与教育无关的私人资料。", true, 1, "了解学生也应遵守必要、适当与隐私边界。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-062", "eth-main", "t2", "t2-s3", "讨论资助安排时，应控制学生家庭困难信息的披露范围。", true, 1, "帮扶不应损害学生人格尊严。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-063", "eth-main", "t2", "t2-s3", "教师把匿名案例用于教学前，仍应注意是否能通过细节识别学生。", true, 1, "去掉姓名并不必然实现充分匿名。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-064", "eth-main", "t2", "t2-s3", "学生有不同于教师的个人兴趣，就说明其品德存在缺陷。", true, 1, "应区分合法个体差异与职业教育中的规范问题。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-065", "eth-main", "t3", "t3-s3", "评价标准需要调整时，应合理说明并考虑对学生的公平影响。", true, 1, "标准变化不宜暗中或任意进行。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-066", "eth-main", "t6", "t6-s2", "教师与学生有亲属关系时，无需考虑可能影响评审公正的利益冲突。", true, 1, "相关情形应按制度披露并处理。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-068", "eth-main", "t4", "t4-s3", "对学生研究贡献的记录，有助于公平协商成果署名。", true, 1, "透明记录有助于减少仅凭身份判断。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-069", "eth-main", "t2", "t2-s3", "教师批评学生行为时，可以直接把一次错误等同于其整个人格。", true, 1, "应评价具体行为并保留改进空间。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
