  put(Q.judge("eth-bal-judge-074", "eth-main", "t2", "t2-s3", "学生重复犯错时，了解原因有助于选择更有效的教育措施。", true, 1, "个体与情境信息对教育判断有价值。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-075", "eth-main", "t2", "t2-s3", "教师可以用公开展示学生病历作为提供学习帮助的必要交换条件。", true, 1, "帮助不应附加侵害隐私和尊严的不当条件。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-076", "eth-main", "t2", "t2-s2", "帮助学生制订可行计划，比长期替其完成作业更有利于自主发展。", true, 1, "教育支持应促进能力而非形成持续依赖。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-077", "eth-main", "t2", "t2-s3", "教师尊重求助学生，应说明建议依据，并尊重学生依法作出的选择。", true, 1, "尊重包含解释与协商，不能把帮助变成要求学生无条件服从个人判断。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-078", "eth-main", "t2", "t2-s3", "为了建立亲密关系，教师可以承诺对任何紧迫安全风险都绝不求助。", true, 1, "保密应有明确的安全和专业边界。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-079", "eth-main", "t2", "t2-s3", "对超出自身专业能力的心理问题，教师应考虑适当转介。", true, 1, "不能把一般关怀等同于专业诊疗能力。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-081", "eth-main", "t2", "t2-s3", "在必要援助中，信息共享应尽量限定于保护安全所需的范围。", true, 1, "求助并不意味着可以任意公开全部私人信息。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
