  put(Q.judge("eth-bal-judge-086", "eth-main", "t2", "t2-s3", "教师可以在规则范围内针对正当特殊情况提供适当学习安排。", true, 1, "合理便利和支持不等于任意徇私。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-087", "eth-main", "t2", "t2-s3", "处理师生冲突时，先核实双方所述事实有助于减少误解。", true, 1, "倾听和核实能够支持更公正的教育判断。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-088", "eth-main", "t3", "t3-s1", "教书育人既关注知识理解，也关注责任意识与人格发展。", true, 1, "不能把教育效果只简化为知识记忆量。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-089", "eth-main", "t3", "t3-s1", "专业课程没有任何与社会责任讨论相联系的可能。", true, 1, "不同专业均可能涉及真实实践中的责任和影响。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-090", "eth-main", "t3", "t3-s1", "把真实专业问题与价值判断结合，通常比脱离内容的生硬口号更有教育意义。", true, 1, "育人应遵循学科和学生成长规律。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
