  put(Q.judge("eth-bal-judge-093", "eth-main", "t2", "t2-s2", "教师可以为了提高就业率，在推荐材料中虚构学生未完成的经历。", true, 1, "支持学生发展不能通过伪造事实实现。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-094", "eth-main", "t3", "t3-s3", "指导新工具使用时，应说明输出核验与成果真实性的责任。", true, 1, "工具便利不能排除独立思考和诚信要求。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-095", "eth-main", "t3", "t3-s3", "只要使用生成式工具，就不需要学生理解自己提交的答案。", true, 1, "学习成果仍应体现学生掌握与负责使用。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-096", "eth-main", "t3", "t3-s3", "实践教学应有学习目标、指导反馈和适当安全安排。", true, 1, "实践不只是安排外出或完成工作量。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-097", "eth-main", "t3", "t3-s2", "教师把学生长期当作与课程无关的私人劳力，不能以实践教学名义正当化。", true, 1, "实践任务应有育人关联并保护学生权益。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-098", "eth-main", "t3", "t3-s3", "对学生作业中的共性错误进行分析，可以帮助教师改进后续教学。", true, 1, "对学习效果负责需要使用反馈证据。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
  put(Q.judge("eth-bal-judge-099", "eth-main", "t3", "t3-s3", "育人责任意味着只评价学生是否认同教师个人偏好，而不看事实论证。", true, 1, "价值引导应与理性、证据及专业标准相联系。"), "职业道德知识点与教学情境平衡补充·自编（v1.10.0）");
