  put(Q.single("eth-r11-single-001", "eth-main", "t1", "t1-s1", "依据《高等教育法》，高校开展教学、科学研究和社会服务时应当以（　　）为中心。", ["培养人才", "扩大个人收入", "争取媒体流量", "增加校产交易次数"], "A", 2, "高校承担多项职能，但法律明确以人才培养为中心，其他职能不能替代育人责任。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-002", "eth-main", "t1", "t1-s1", "高校教师把科研中的新问题转化为学生可探究的课程任务，体现（　　）。", ["科研可以永久替代教学", "学生只需替教师完成产量", "课程只承担商业宣传", "科研与人才培养相互促进"], "D", 2, "科研资源进入教学可以促进探究与学习，但应提供适当指导并保护学生权益。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-003", "eth-main", "t1", "t1-s1", "高校面向社区开展可靠的科学知识普及，主要体现（　　）职能。", ["仅限校内学历授予", "教师私人利益交换", "社会服务", "替代一切行政管理"], "C", 2, "运用知识回应社会需要属于社会服务，科普也应遵循真实与负责的要求。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-004", "eth-main", "t1", "t1-s1", "把大学职能理解为只颁发学历证书，主要忽视了（　　）。", ["学校无需保证学习质量", "人才培养、知识创造与社会贡献的联系", "学生毕业后无需承担任何责任", "所有研究都必须立刻盈利"], "B", 2, "高校不只是证书发放机构，教学、科研与社会服务应共同促进育人和社会发展。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-005", "eth-main", "t2", "t2-s1", "说教育具有道德意义，较恰当的理由是（　　）。", ["教育会影响人的发展并涉及如何对待人的价值选择", "只要有考试就自动形成全部美德", "教育只涉及设备配置", "任何教育手段都因目的良好而正当"], "A", 2, "教育不仅传递信息，也涉及尊严、机会、责任与发展，目的正当不能免除对手段的审查。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-006", "eth-main", "t2", "t2-s1", "教师以培养自信为由公开编造学生获奖经历，其道德问题在于（　　）。", ["只要学生高兴就没有问题", "育人可以免除事实核实", "教师不需要考虑行为后果", "用不诚实手段实施看似善意的教育"], "D", 2, "教育应把价值目标与诚实手段结合，帮助学生不能成为制造虚假事实的理由。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-007", "eth-main", "t2", "t2-s1", "教师称“学生是有自身意愿和尊严的人”，最直接要求（　　）。", ["由教师替学生决定全部私人事务", "取消所有合理学习要求", "教育安排尊重其主体地位与正当权利", "把学生当作可任意加工的物品"], "C", 2, "尊重学生是道德教育的前提，同时可以通过解释和适当规则培养其责任。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-009", "eth-main", "t2", "t2-s2", "学生参与社区志愿服务前，指导教师首先应组织（　　）。", ["明确任务、必要培训及风险和权益说明", "只拍宣传照片而不安排任务", "用志愿名义免除安全责任", "隐瞒活动要求以免学生退出"], "A", 2, "学生活动指导需要事前准备、知情及适当保护，公益目的不排除这些责任。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-010", "eth-main", "t2", "t2-s2", "评选学生活动优秀成员时，较合适的依据是（　　）。", ["谁与教师私人关系最好", "谁承担了教师的私人差事", "谁在群里点赞最多", "事先说明的标准与实际参与贡献"], "D", 2, "活动评价应围绕育人目标与真实贡献，不把私人关系或无关行为作为奖励依据。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-011", "eth-main", "t3", "t3-s2", "教师长期照读错误讲义并拒绝核实学生指出的问题，主要违背（　　）。", ["完成点名即可免除备课责任", "教师无需持续更新知识", "对教学内容与学习效果负责的要求", "只有课外科研才需准确"], "C", 2, "教学道德包括认真准备、实事求是与改进，完成课时不能替代内容质量。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-012", "eth-main", "t3", "t3-s2", "教师为了增加课程通过率，授意学生购买代写服务，其问题是（　　）。", ["学生付费后教师即无责任", "以表面成绩损害真实学习与诚信", "代写能自动提高学习能力", "通过率是唯一教学道德标准"], "B", 2, "教学评价应反映真实学习，不能为追求指标而组织或默许学业造假。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-013", "eth-main", "t3", "t3-s2", "教师把强制购买自己高价私人资料作为参加考核的条件，首先应审查（　　）。", ["是否利用教学权限进行不当利益绑定", "资料封面是否醒目", "销售页面是否流行", "是否能提高私人销量"], "A", 2, "教学资源选择应服务学生学习，不能把考核权限变成向学生强制获利的工具。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-014", "eth-main", "t3", "t3-s4", "教学道德的理想追求超越最低合规，较能体现为（　　）。", ["只求形式上不被投诉", "一味讨好学生以换取高评教", "认为教师无需任何规范", "持续改善学习环境并促进学生自主成长"], "D", 2, "理想追求并非取消底线，而是在履职基础上不断改善教育质量与发展支持。"), "按用户教材目录补充的自编练习（v1.11.0）");
  put(Q.single("eth-r11-single-015", "eth-main", "t3", "t3-s4", "在完成必要指导后，教师进一步帮助学生学会自我评价，体现（　　）。", ["取消所有学习标准", "仅追求教师个人受欢迎", "由提供帮助走向促进自主发展的育人追求", "永久替学生决定全部学习事务"], "C", 2, "好的指导不仅完成眼前任务，还帮助学生形成独立判断与持续学习能力。"), "按用户教材目录补充的自编练习（v1.11.0）");
